import{z as s,x as o,o as n,c as d,q as A,j as r,D as e,d as B,s as i,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"私募与公募的约束差异","description":"","frontmatter":{"title":"私募与公募的约束差异","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-fund-constraints.md","filePath":"quant/cn-fund-constraints.md","lastUpdated":1791063341000}'),p={name:"quant/cn-fund-constraints.md"};function C(D,E,u,c,F,m){const t=o("Mermaid");return n(),d("div",null,[E[2]||(E[2]=A('<h1 id="私募与公募的约束差异" tabindex="-1">私募与公募的约束差异 <a class="header-anchor" href="#私募与公募的约束差异" aria-label="Permalink to &quot;私募与公募的约束差异&quot;">​</a></h1><div class="epigraph"><p>同一个信号装进不同载体，可行集立刻不同：约束清单逐项告诉你谁定的、怎么度量、违反了怎样，比「公募保守、私募灵活」的印象有用得多。</p><footer>—— 据公募基金运作与私募基金监管自律口径整理</footer></div><p><a href="/quant/cn-vendor-comparison">上一课</a>把数据栈选好；同样的策略放进不同载体，约束集完全不同。<a href="/quant/cn-public-quant">公募量化与指增</a>与<a href="/quant/cn-private-neutral">私募与中性策略</a>分别写过两类产品的运作，本课把它们放上同一张约束清单对照。策略迁移的失败常死在载体而不是信号：先查清单，再谈移植。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公募基金申赎开放，日终要应付净赎回，重仓小票的组合要为流动性留折价；定期披露的前十大重仓让策略方向在季报后半个公开；持股集中度与流动性管理规则约束持仓形态与换手。私募面向合格投资者，开放安排写进合同，工具箱更宽，但要承担业绩报酬驱动的规模冲动与同严格的报备义务（<a href="/quant/cn-programmatic-filing">程序化交易的报备实践</a>的台账在私募侧同样适用）。同一套信号，两边的可交易宇宙、换手上界与容量都不一样，不查清单就移植，等于赌约束不存在。</p><p><span class="marginnote">直觉类比：公募像公交车，线路站点全部公示、上下客自由，只能开宽敞大道；私募像包车，路线在合同里谈好，可以走小路，但乘客门槛与费用条款也写死在合同里。同一批货（信号）装车前，先看车能走哪条路，而不是先装货再改路线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>约束清单七行，每行写「谁定、怎么量、违反怎样」。客户与申赎：公募面向公众、每日申赎、有流动性管理义务；私募限合格投资者，开放频率合同约定。投资范围：公募参与股指期货以套期保值为目的、比例受限，衍生品品种有限；私募工具箱更宽，含场外工具，但报备义务同在。集中度：公募受「双十」类约束——单只基金持单一证券、同一管理人旗下全部基金合计持单一证券，各有一条线；私募按合同自定但有底线规则。披露：公募定期公开报告与重仓；私募只对投资者披露。杠杆：公募总体低杠杆；私募依合同与保证金。费率：公募固定管理费；私募管理费加业绩报酬，高水位机制见<a href="/quant/performance-fee-hwm">业绩费与高水位</a>。考核：公募对基准的跟踪误差与同类排名；私募绝对收益与回撤。</p><p><span class="marginnote">术语翻译：私募业绩报酬的「高水位法」，就是只有净值超过历史最高计提点才提费——净值从 1.20 回撤到 1.00，再涨回 1.15 的过程中一分钱业绩报酬都不提，要等越过 1.20 才恢复计提。它防的是「亏了照收管理费、回本马上再提一次」的重复收费。</span></p>',9)),(n(),r(l,null,{default:e(()=>[i(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E5%90%8C%E4%B8%80%E5%A5%97%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20PUB%5B%22%E5%85%AC%E5%8B%9F%E8%BD%BD%E4%BD%93%22%5D%0A%20%20SIG%20--%3E%20PRI%5B%22%E7%A7%81%E5%8B%9F%E8%BD%BD%E4%BD%93%22%5D%0A%20%20PUB%20--%3E%20PC%5B%22%E7%94%B3%E8%B5%8E%E5%BC%80%E6%94%BE%2B%E6%8A%AB%E9%9C%B2%2B%E5%8F%8C%E5%8D%81%E9%9B%86%E4%B8%AD%E5%BA%A6%22%5D%0A%20%20PRI%20--%3E%20RC%5B%22%E5%90%88%E6%A0%BC%E6%8A%95%E8%B5%84%E8%80%85%2B%E5%B7%A5%E5%85%B7%E5%AE%BD%2B%E4%B8%9A%E7%BB%A9%E6%8A%A5%E9%85%AC%22%5D%0A%20%20PC%20--%3E%20PCAP%5B%22%E5%AE%B9%E9%87%8F%E5%A4%A7%EF%BC%8C%E6%8D%A2%E6%89%8B%E4%B8%8E%E6%8C%81%E4%BB%93%E5%BD%A2%E6%80%81%E5%8F%97%E9%99%90%22%5D%0A%20%20RC%20--%3E%20RCAP%5B%22%E7%81%B5%E6%B4%BB%EF%BC%8C%E4%BD%86%E5%88%B8%E6%BA%90%E8%B4%B4%E6%B0%B4%E4%B8%8E%E6%8A%A5%E5%A4%87%E5%90%8C%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("约束差异塑造策略形态。公募指增被推向容量大、换手适中、以跟踪误差为纲的形态，超额随规模衰减可观测（"),a("a",{href:"/quant/index-enhancement-decay"},"指增产品超额衰减"),B("）；私募中性的空头腿把券息与贴水成本（前两课的机制）和绝对收益考核一起写进产品结构。行为后果也不同：公募季报披露创造可预测的调仓流，私募的业绩报酬在计提窗口附近制造风险切换动机。选载体因此是策略设计的一部分：把日内信号装进公募载体，先输在回转约束上；把低换手深度信号装进私募，先输在费用结构上。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"「双十」的第二条线常被漏算：同一管理人旗下全部基金合计持有一家公司的证券不得超过该证券的一成——大盘量化组合的持仓上限由这一条给出，不是由单只基金的那条。")],-1)),(n(),r(l,null,{default:e(()=>[i(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOVE%5B%22%E4%BF%A1%E5%8F%B7%E8%A6%81%E4%BB%8E%20A%20%E8%BD%BD%E4%BD%93%E8%BF%81%E5%88%B0%20B%20%E8%BD%BD%E4%BD%93%22%5D%20--%3E%20Q1%7B%22%E6%97%A5%E5%86%85%E6%8D%A2%E6%89%8B%E9%AB%98%E5%90%97%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20ROT%5B%22%E5%85%AC%E5%8B%9F%E5%9B%9E%E8%BD%AC%E4%B8%8E%E6%8D%A2%E6%89%8B%E7%BA%A6%E6%9D%9F%E5%85%88%E6%92%9E%E7%BA%BF%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20Q2%7B%22%E6%8C%81%E4%BB%93%E5%81%8F%E5%B0%8F%E7%9B%98%E5%90%97%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20CONC%5B%22%E5%8F%8C%E5%8D%81%E9%9B%86%E4%B8%AD%E5%BA%A6%E4%B8%8E%E6%B5%81%E5%8A%A8%E6%80%A7%E6%8A%98%E4%BB%B7%E5%85%88%E6%92%9E%E7%BA%BF%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20Q3%7B%22%E9%9C%80%E8%A6%81%E5%9C%BA%E5%A4%96%E6%88%96%E5%AF%B9%E5%86%B2%E5%B7%A5%E5%85%B7%E5%90%97%3F%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20TOOL%5B%22%E5%85%AC%E5%8B%9F%E5%A5%97%E4%BF%9D%E6%AF%94%E4%BE%8B%E5%8F%97%E9%99%90%EF%BC%8C%E6%94%B9%E8%B5%B0%E7%A7%81%E5%8B%9F%22%5D%0A%20%20Q3%20--%3E%7C%22%E5%90%A6%22%7C%20BOTH%5B%22%E4%B8%A4%E8%BD%BD%E4%BD%93%E7%9A%86%E5%8F%AF%EF%BC%9A%E6%AF%94%E8%B4%B9%E7%8E%87%E3%80%81%E6%8A%AB%E9%9C%B2%E4%B8%8E%E8%80%83%E6%A0%B8%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写监管套利与通道安排；具体比例与开放条款以基金合同、托管协议与当期规则为准；两类载体的份额结构与申赎费细节不在本课。</p><p><span class="marginnote">常见误区：以为私募「绝对收益」考核等于没有约束。实际上合同里的预警线、止损线与高水位共同构成一条隐形基准——净值逼近预警线时会被动降仓，约束的是回撤深度而不是对基准的偏离，与公募的跟踪误差考核殊途同归。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>载体对照用七行清单：客户、范围、集中度、披露、杠杆、费率、考核。</li><li>公募形态由申赎、披露与双十集中度塑造；私募由工具箱、业绩报酬与绝对收益考核塑造。</li><li>迁移策略先查载体约束：日内信号输在回转约束，深度信号输在费用结构。</li><li>出处：公募基金运作管理办法与私募基金监管自律口径；两类产品运作见<a href="/quant/cn-public-quant">公募量化与指增</a>、<a href="/quant/cn-private-neutral">私募与中性策略</a>。</li></ul>',5))])}const q=s(p,[["render",C]]);export{h as __pageData,q as default};
